import { useCallback, useEffect, useMemo, useState } from "react";
import { Link, useParams } from "react-router-dom";
import {
  FiAlertCircle,
  FiAward,
  FiCalendar,
  FiCheckCircle,
  FiClock,
  FiRefreshCw,
  FiTrendingUp,
  FiUsers,
  FiXCircle,
} from "react-icons/fi";
import { PATHS } from "../../app/router/paths";
import {
  getTrainerCourseAttendanceEligibility,
  getTrainerCourseAttendanceSummary,
  getTrainerCourseStudentAttendance,
  getTrainerSessionAttendance,
} from "../api/trainerAttendanceApi";

const emptyReport = {
  courseId: "",
  courseTitle: "Attendance report",
  trainerId: "",
  sessionId: "",
  sessionTitle: "Session attendance",
  totalStudents: 0,
  totalSessions: 0,
  completedSessions: 0,
  presentCount: 0,
  lateCount: 0,
  absentCount: 0,
  attendancePercentage: 0,
  students: [],
  sessions: [],
  eligibility: null,
};

function formatPercent(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "0%";
  return `${number.toFixed(number % 1 === 0 ? 0 : 1)}%`;
}

function formatDate(value) {
  if (!value) return "-";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

function StatCard({ label, value, icon: Icon, tone = "slate" }) {
  const toneClass =
    tone === "green"
      ? "bg-emerald-50 text-emerald-700"
      : tone === "amber"
        ? "bg-amber-50 text-amber-700"
        : tone === "red"
          ? "bg-red-50 text-red-700"
          : "bg-slate-50 text-slate-700";

  return (
    <div className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm">
      <div className={`inline-flex h-9 w-9 items-center justify-center rounded-lg ${toneClass}`}>
        <Icon />
      </div>
      <div className="mt-3 text-xl font-extrabold text-slate-950">{value}</div>
      <div className="mt-1 text-xs font-bold uppercase tracking-wider text-slate-500">{label}</div>
    </div>
  );
}

function ProgressBar({ value }) {
  const width = Math.max(0, Math.min(100, Number(value) || 0));
  return (
    <div className="h-2 overflow-hidden rounded-full bg-slate-100">
      <div className="h-full rounded-full bg-[#006b58]" style={{ width: `${width}%` }} />
    </div>
  );
}

function EmptyState({ title, message }) {
  return (
    <div className="rounded-xl border border-dashed border-slate-200 bg-slate-50 p-8 text-center">
      <div className="text-base font-extrabold text-slate-900">{title}</div>
      <p className="mt-1 text-sm text-slate-500">{message}</p>
    </div>
  );
}

export default function TrainerAttendancePage({ view = "course" }) {
  const { courseId = "", sessionId = "" } = useParams();
  const [report, setReport] = useState(emptyReport);
  const [eligibilityReport, setEligibilityReport] = useState(null);
  const [loading, setLoading] = useState(true);
  const [eligibilityLoading, setEligibilityLoading] = useState(false);
  const [error, setError] = useState("");
  const [eligibilityError, setEligibilityError] = useState("");

  const isSessionView = view === "session";
  const isStudentsView = view === "students";

  const title = isSessionView
    ? report.sessionTitle || "Session attendance"
    : report.courseTitle || "Course attendance";
  const subtitle = isSessionView
    ? "Session-wise attendance report finalized after class completion."
    : isStudentsView
      ? "Student-wise attendance table for course completion review."
      : "Course attendance summary with session-wise progress.";

  const loadReport = useCallback(async () => {
    setLoading(true);
    setError("");
    try {
      let nextReport;
      if (isSessionView) {
        nextReport = await getTrainerSessionAttendance(sessionId);
      } else if (isStudentsView) {
        nextReport = await getTrainerCourseStudentAttendance(courseId);
      } else {
        nextReport = await getTrainerCourseAttendanceSummary(courseId);
      }
      setReport({ ...emptyReport, ...nextReport });
    } catch (err) {
      setError(err?.message || "Unable to load attendance report.");
    } finally {
      setLoading(false);
    }
  }, [courseId, isSessionView, isStudentsView, sessionId]);

  useEffect(() => {
    loadReport();
  }, [loadReport]);

  useEffect(() => {
    if (!courseId || isSessionView) return;
    let ignore = false;
    setEligibilityLoading(true);
    setEligibilityError("");
    getTrainerCourseAttendanceEligibility(courseId)
      .then((next) => {
        if (!ignore) setEligibilityReport(next);
      })
      .catch((err) => {
        if (!ignore) setEligibilityError(err?.message || "Eligibility preview is not available yet.");
      })
      .finally(() => {
        if (!ignore) setEligibilityLoading(false);
      });
    return () => {
      ignore = true;
    };
  }, [courseId, isSessionView]);

  const students = useMemo(() => report.students || [], [report.students]);
  const sessions = useMemo(() => report.sessions || [], [report.sessions]);
  const eligibleCount = useMemo(() => {
    const source = eligibilityReport?.students?.length ? eligibilityReport.students : students;
    return source.filter((student) =>
      String(student.eligibilityStatus || "").toLowerCase().includes("eligible")
    ).length;
  }, [eligibilityReport, students]);

  return (
    <main className="min-h-dvh bg-[#f4f7f6] text-slate-950">
      <section className="border-b border-slate-200 bg-white">
        <div className="mx-auto max-w-7xl px-4 py-7 sm:px-6">
          <Link
            to={PATHS.TRAINER_DASHBOARD}
            className="text-xs font-extrabold uppercase tracking-widest text-[#006b58]"
          >
            Trainer dashboard
          </Link>
          <div className="mt-3 flex flex-col justify-between gap-4 lg:flex-row lg:items-end">
            <div>
              <h1 className="text-2xl font-black tracking-tight text-slate-950 sm:text-3xl">
                {title}
              </h1>
              <p className="mt-2 max-w-2xl text-sm leading-relaxed text-slate-500">{subtitle}</p>
            </div>
            <button
              type="button"
              onClick={loadReport}
              className="inline-flex h-11 items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white px-5 text-sm font-extrabold text-slate-700 transition-colors hover:border-[#006b58]"
            >
              <FiRefreshCw className={loading ? "animate-spin" : ""} />
              Refresh
            </button>
          </div>
        </div>
      </section>

      <section className="mx-auto max-w-7xl px-4 py-6 sm:px-6">
        {error ? (
          <div className="mb-5 flex items-start gap-2 rounded-xl border border-red-100 bg-red-50 px-4 py-3 text-sm font-semibold text-red-700">
            <FiAlertCircle className="mt-0.5 flex-shrink-0" />
            <span>{error}</span>
          </div>
        ) : null}

        {loading ? (
          <div className="rounded-2xl border border-slate-200 bg-white p-10 text-center shadow-sm">
            <span className="mx-auto block h-9 w-9 animate-spin rounded-full border-2 border-slate-200 border-t-[#00342b]" />
            <div className="mt-3 text-lg font-extrabold">Loading attendance report</div>
            <p className="mt-1 text-sm text-slate-500">Fetching finalized attendance data.</p>
          </div>
        ) : (
          <div className="space-y-6">
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-7">
              <StatCard label="Total Students" value={report.totalStudents} icon={FiUsers} />
              <StatCard label="Total Sessions" value={report.totalSessions} icon={FiCalendar} />
              <StatCard label="Completed" value={report.completedSessions} icon={FiCheckCircle} />
              <StatCard label="Present" value={report.presentCount} icon={FiCheckCircle} tone="green" />
              <StatCard label="Late" value={report.lateCount} icon={FiClock} tone="amber" />
              <StatCard label="Absent" value={report.absentCount} icon={FiXCircle} tone="red" />
              <StatCard
                label="Average"
                value={formatPercent(report.attendancePercentage)}
                icon={FiTrendingUp}
                tone="green"
              />
            </div>

            {!isSessionView ? (
              <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5">
                <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center">
                  <div>
                    <h2 className="text-lg font-extrabold">Certificate eligibility preview</h2>
                    <p className="mt-1 text-sm text-slate-500">
                      Preview only. Certificate request action will be added later.
                    </p>
                  </div>
                  <div className="rounded-xl bg-emerald-50 px-4 py-2 text-sm font-extrabold text-emerald-800">
                    {eligibilityLoading ? "Checking..." : `${eligibleCount} eligible`}
                  </div>
                </div>
                {eligibilityError ? (
                  <div className="mt-4 flex items-start gap-2 rounded-xl border border-amber-100 bg-amber-50 px-4 py-3 text-sm font-semibold text-amber-800">
                    <FiAward className="mt-0.5 flex-shrink-0" />
                    <span>{eligibilityError}</span>
                  </div>
                ) : null}
              </div>
            ) : null}

            {!isStudentsView ? (
              <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5">
                <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center">
                  <div>
                    <h2 className="text-lg font-extrabold">Session-wise attendance report</h2>
                    <p className="mt-1 text-sm text-slate-500">
                      Present, late, absent, and attendance percentage per completed session.
                    </p>
                  </div>
                  {courseId ? (
                    <Link
                      to={`/trainer/courses/${encodeURIComponent(courseId)}/students-attendance`}
                      className="inline-flex h-10 items-center justify-center rounded-xl bg-[#00342b] px-4 text-sm font-extrabold text-white"
                    >
                      Student table
                    </Link>
                  ) : null}
                </div>

                <div className="mt-5 overflow-x-auto">
                  {sessions.length ? (
                    <table className="min-w-full text-left text-sm">
                      <thead>
                        <tr className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500">
                          <th className="px-3 py-3 font-extrabold">Date</th>
                          <th className="px-3 py-3 font-extrabold">Session</th>
                          <th className="px-3 py-3 font-extrabold">Present</th>
                          <th className="px-3 py-3 font-extrabold">Late</th>
                          <th className="px-3 py-3 font-extrabold">Absent</th>
                          <th className="px-3 py-3 font-extrabold">Attendance %</th>
                        </tr>
                      </thead>
                      <tbody>
                        {sessions.map((session) => (
                          <tr key={session.sessionId || `${session.date}-${session.sessionTitle}`} className="border-b border-slate-100">
                            <td className="px-3 py-3 font-semibold text-slate-600">{formatDate(session.date)}</td>
                            <td className="px-3 py-3 font-extrabold text-slate-900">{session.sessionTitle}</td>
                            <td className="px-3 py-3 text-emerald-700">{session.presentCount}</td>
                            <td className="px-3 py-3 text-amber-700">{session.lateCount}</td>
                            <td className="px-3 py-3 text-red-700">{session.absentCount}</td>
                            <td className="px-3 py-3">
                              <div className="min-w-32">
                                <div className="mb-1 font-extrabold">{formatPercent(session.attendancePercentage)}</div>
                                <ProgressBar value={session.attendancePercentage} />
                              </div>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  ) : (
                    <EmptyState
                      title="No session attendance yet"
                      message="Session-wise attendance will appear after sessions are completed."
                    />
                  )}
                </div>
              </div>
            ) : null}

            <div className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm sm:p-5">
              <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center">
                <div>
                  <h2 className="text-lg font-extrabold">Student-wise attendance table</h2>
                  <p className="mt-1 text-sm text-slate-500">
                    Review each student's attendance before course completion and certificate request.
                  </p>
                </div>
              </div>

              <div className="mt-5 overflow-x-auto">
                {students.length ? (
                  <table className="min-w-full text-left text-sm">
                    <thead>
                      <tr className="border-b border-slate-200 text-xs uppercase tracking-wider text-slate-500">
                        <th className="px-3 py-3 font-extrabold">Student Name</th>
                        <th className="px-3 py-3 font-extrabold">Email</th>
                        <th className="px-3 py-3 font-extrabold">Present</th>
                        <th className="px-3 py-3 font-extrabold">Late</th>
                        <th className="px-3 py-3 font-extrabold">Absent</th>
                        <th className="px-3 py-3 font-extrabold">Attended</th>
                        <th className="px-3 py-3 font-extrabold">Attendance %</th>
                        <th className="px-3 py-3 font-extrabold">Eligibility</th>
                      </tr>
                    </thead>
                    <tbody>
                      {students.map((student) => (
                        <tr key={student.studentId || student.email} className="border-b border-slate-100">
                          <td className="px-3 py-3 font-extrabold text-slate-900">{student.fullName}</td>
                          <td className="px-3 py-3 font-semibold text-slate-500">{student.email || "-"}</td>
                          <td className="px-3 py-3 text-emerald-700">{student.presentCount}</td>
                          <td className="px-3 py-3 text-amber-700">{student.lateCount}</td>
                          <td className="px-3 py-3 text-red-700">{student.absentCount}</td>
                          <td className="px-3 py-3 font-semibold">
                            {student.attendedCount}/{student.totalSessions || report.totalSessions}
                          </td>
                          <td className="px-3 py-3">
                            <div className="min-w-32">
                              <div className="mb-1 font-extrabold">{formatPercent(student.attendancePercentage)}</div>
                              <ProgressBar value={student.attendancePercentage} />
                            </div>
                          </td>
                          <td className="px-3 py-3">
                            <span className="inline-flex rounded-full bg-slate-50 px-2.5 py-1 text-xs font-extrabold text-slate-700">
                              {student.eligibilityStatus}
                            </span>
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                ) : (
                  <EmptyState
                    title="No student attendance yet"
                    message="Student-wise attendance will appear after students join completed sessions."
                  />
                )}
              </div>
            </div>
          </div>
        )}
      </section>
    </main>
  );
}
